{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-82879ad120c75e2c","type":"tool_result","content":"required:\n  epic_id:\n    type: string\n  title:\n    type: string\n  parent_strat:\n    type: string\n    pattern: ^RHAISTRAT-\\d+$\n  component:\n    type: string\n  team:\n    type: string\n  type:\n    type: string\n    enum:\n    - Implementation\n    - Investigation\n  priority:\n    type: string\n    enum:\n    - P0\n    - P1\n    - P2\noptional:\n  implementation_type:\n    type: string\n    enum:\n    - docs-authoring\n    - konflux-onboarding\n    - license-validation\n    - repo-onboarding\n    default: null\n  dependencies:\n    type: list\n    default: []\n  ai_signals:\n    type: dict\n    default: null\n    fields:\n      change_specificity:\n        type: int\n      pattern_precedent:\n        type: int\n      adapter_pattern:\n        type: int\n      existing_foundation:\n        type: int\n      open_questions:\n        type: int\n      external_dependency:\n        type: int\n      human_process_gates:\n        type: int\n      repo_access:\n        type: int\n      architecture_claims:\n        type: int\n  investigation_signals:\n    type: dict\n    default: null\n    fields:\n      question_specificity:\n        type: int\n        enum:\n        - -1\n        - 0\n        - 1\n      source_accessibility:\n        type: int\n        enum:\n        - 0\n        - 1\n      local_runnability:\n        type: int\n        enum:\n        - 0\n        - 1\n      cluster_hardware_dependence:\n        type: int\n        enum:\n        - -2\n        - -1\n        - 0\n      human_judgment_required:\n        type: int\n        enum:\n        - -2\n        - -1\n        - 0\n  ai_implementability:\n    type: string\n    enum:\n    - High\n    - Medium\n    - Low\n    default: null\n  ai_implementability_score:\n    type: int\n    default: null\n  jira_key:\n    type: string\n    pattern: ^[A-Z][A-Z0-9_]*-\\d+$\n    default: nu