 Criteria\", (\"acceptance criteria\",)),\n            (\"HLR Traceability\", (\"hlr traceability\", \"traceability\"))]\n\nPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n\nFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n\n\ndef read_frontmatter(path):\n    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n    with open(path, encoding=\"utf-8\") as f:\n        content = f.read()\n    m = FRONTMATTER_RE.match(content)\n    if not m:\n        return {}, content\n    try:\n        data = yaml.safe_load(m.group(1))\n    except yaml.YAMLError:\n        return {}, content\n    if not isinstance(data, dict):\n        return {}, content\n    return data, content[m.end():]\n\n\ndef body_headings(body):\n    heads = []\n    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n    return heads\n\n\ndef load_epics(artifacts_dir, strat_id):\n    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n\n    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n    \"\"\"\n    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n    if not os.path.isdir(task_dir):\n        return {}\n    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n    epics = {}\n    for name in sorted(os.listdir(task_dir)):\n        m = pat.match(name)","is_error":false}]},"parent_tool_use_id":"chatcmpl-tool-9cbc04831ea090fb","agent_id":"a7506effac068fb42","session_id":"975609a4-9996-4dcf-a42c-1d087396c61b","uuid":"45efe5b4-f9e9-4403-a2a7-98cb3f8445f5","timestamp":"2026-10-22T06:27:19.928Z","tool_result_meta":[{"id":"chatcmpl-tool-82879ad120c75e2c","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}],"subagent_type":"general-purpose","task_description":"Decompose RHAISTRAT-8008"}
